window.SR_BOOK = {"title":"Speak Reggaeton","subtitle":"Spanish Slang for Beginners with Online Audio: Puerto Rican Expressions, Real-Life Dialogues, and Latin Music Culture","author":"José Revaliente","cefr":"A1–A2","source":"Speak Reggaeton V3.3 Google Docs (editorially audited working copy)","source_url":"https://docs.google.com/document/d/1yk28kW8Z2vScgG_Kk763aVGvGDHUYBsLY2k-uiOanlI/edit","notes":"Dictionary definitions are excerpted from user's own manuscript. Case links distinguish dialogue occurrences from supplementary teaching vocabulary. Audio links supplied by publisher, not independently quality-verified.","count":122,"entries":[{"term":"a fuego","meaning":"Excellent, amazing or exciting in the approving informal sense.","region_and_use":"Puerto Rico. RECOGNISE FIRST.","spanish_example":"La pista quedó a fuego.","english_example":"The track turned out great.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.discoverpuertorico.com/article/puerto-ricos-reggaeton-slang-explained ; https://plpr.uh.edu/s/es/page/glosario","case":"04","in_dialogue":false,"learning_status":"recognition"},{"term":"a las cuatro","meaning":"At four o'clock; this gives a time, not the meaning early or nearby.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Nos vemos a las cuatro.","english_example":"See you at four.","find_it":"Case 03. Dialogue: Case 03, Case 12.","sources":"https://dle.rae.es/hora","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"acicalado (acicalao)","meaning":"Informal representation of acicalado: carefully groomed or smartly dressed. Acicalado is the standard written form; a reduced -ado ending is not exclusive to Puerto Rico.","region_and_use":"general Spanish base; urban/music spelling. RECOGNISE FIRST.","spanish_example":"Luis llegó bien acicalado al concierto.","english_example":"Luis arrived at the concert looking smartly dressed.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/acicalar ; Wood (2009), pp. 45–46.","case":"07","in_dialogue":false,"learning_status":"recognition"},{"term":"al garete","meaning":"Without direction or out of control. The nautical expression also has figurative uses; the Cuban disorder sense and the Puerto Rican informal usage require their respective sources.","region_and_use":"Cuba (ASALE disorder sense); Puerto Rico (usage guide). CONTEXT DEPENDENT.","spanish_example":"La fiesta se fue al garete.","english_example":"The party got out of control.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/garete ; https://www.discoverpuertorico.com/article/puerto-ricos-reggaeton-slang-explained","case":"07","in_dialogue":false,"learning_status":"context"},{"term":"amigo / amiga","meaning":"Friend in the relationship sense taught here.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Esta es mi amiga Nora.","english_example":"This is my friend Nora.","find_it":"Case 02. Dialogue: Case 02, Case 03, Case 07, Case 08, Case 09, Case 10, Case 11, Case 12.","sources":"https://dle.rae.es/amigo","case":"02","in_dialogue":true,"learning_status":"active"},{"term":"autobús","meaning":"Bus, a passenger transport vehicle.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"El autobús llega a las ocho.","english_example":"The bus arrives at eight.","find_it":"Case 10. Dialogue: Case 09, Case 10.","sources":"https://dle.rae.es/autob%C3%BAs","case":"10","in_dialogue":true,"learning_status":"active"},{"term":"bacano / bacana","meaning":"Great, excellent or impressive in the approving adjective sense. It has further person-related senses in the Dominican Republic.","region_and_use":"Colombia, Ecuador; Dominican Republic (youth label in ASALE). RECOGNISE FIRST.","spanish_example":"El concierto estuvo bacano.","english_example":"The concert was great.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/bacano","case":"04","in_dialogue":false,"learning_status":"recognition"},{"term":"bailar","meaning":"To dance; general activity, unlike a specific dance label.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Quieres bailar?","english_example":"Do you want to dance?","find_it":"Case 06. Dialogue: Case 03, Case 06, Case 12.","sources":"https://dle.rae.es/bailar","case":"06","in_dialogue":true,"learning_status":"active"},{"term":"bajo","meaning":"Bass in a music discussion; low as an adjective in other settings.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"El bajo suena muy fuerte.","english_example":"The bass sounds very loud.","find_it":"Case 05. Dialogue: Case 05.","sources":"https://dle.rae.es/bajo","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"beat","meaning":"Rhythmic or instrumental backing in this music discussion; the word can have a narrower pulse-related meaning in other contexts.","region_and_use":"music terminology, English borrowing. CONTEXT DEPENDENT.","spanish_example":"Me gusta el beat de esta pista.","english_example":"I like the beat of this track.","find_it":"Case 05. Dialogue: Case 05, Case 12.","sources":"https://mtosmt.org/issues/mto.17.23.4/mto.17.23.4.komaniecki.html","case":"05","in_dialogue":true,"learning_status":"context"},{"term":"bellaquear","meaning":"To engage in sexual activity or sexual play in the recorded Puerto Rican sense; it does not merely mean to feel attraction or to dance.","region_and_use":"Puerto Rico; other senses elsewhere. ADULT / TABOO — RECOGNITION ONLY.","spanish_example":"Luis buscó el significado de «bellaquear» antes de interpretar el comentario.","english_example":"Luis looked up the meaning of “bellaquear” before interpreting the comment.","find_it":"Case 08. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/bellaquear","case":"08","in_dialogue":false,"learning_status":"recognition_sensitive"},{"term":"billete","meaning":"Banknote in the money example; it can also mean a ticket in other contexts.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Tengo un billete grande.","english_example":"I have a large banknote.","find_it":"Case 09. Dialogue: Case 09.","sources":"https://dle.rae.es/billete","case":"09","in_dialogue":true,"learning_status":"active"},{"term":"bocina","meaning":"Loudspeaker in the sense used in these scenes. Elsewhere or in another sentence it may refer to a horn or other device.","region_and_use":"Puerto Rico and other documented American varieties. CONTEXT DEPENDENT.","spanish_example":"La bocina no funciona; no escuchamos la música.","english_example":"The speaker isn't working; we can't hear the music.","find_it":"Case 05. Dialogue: Case 01, Case 05, Case 10.","sources":"https://www.asale.org/damer/bocina","case":"05","in_dialogue":true,"learning_status":"context"},{"term":"bonche","meaning":"Party or gathering for a celebration in the selected sense. Other senses include a large group or quantity, a noisy atmosphere, and further strongly regional meanings.","region_and_use":"Mexico, Cuba, Dominican Republic, Puerto Rico, Venezuela for the celebration sense. RECOGNISE FIRST.","spanish_example":"Después del concierto hicieron un bonche.","english_example":"They had a party after the concert.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/bonche","case":"03","in_dialogue":false,"learning_status":"recognition"},{"term":"bregar","meaning":"To try to accomplish something, or help with something, in recorded Puerto Rican uses. The general verb also means to struggle or work with effort. A separate Puerto Rican sexual euphemism makes context important.","region_and_use":"general Spanish and Puerto Rican senses, separated. CONTEXT DEPENDENT.","spanish_example":"Luis brega con la organización del concierto.","english_example":"Luis works through the concert arrangements.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/bregar ; https://dle.rae.es/bregar","case":"04","in_dialogue":false,"learning_status":"context"},{"term":"brutal","meaning":"Great, magnificent or amazing in the positive colloquial sense; it can also describe violence or extreme intensity in other contexts.","region_and_use":"general colloquial Spanish; no exclusive Puerto Rican claim. CONTEXT DEPENDENT.","spanish_example":"¡El video quedó brutal!","english_example":"The video turned out amazing!","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/brutal","case":"04","in_dialogue":false,"learning_status":"context"},{"term":"café","meaning":"Coffee, a serving of coffee, or a café establishment according to context.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Quieres tomar un café?","english_example":"Would you like a coffee?","find_it":"Case 03. Dialogue: Case 03, Case 08, Case 09, Case 12.","sources":"https://dle.rae.es/caf%C3%A9","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"cambio","meaning":"Change in the cash example; exchange or change more generally.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Necesito cambio para el autobús.","english_example":"I need change for the bus.","find_it":"Case 09. Dialogue: Case 09.","sources":"https://dle.rae.es/cambio","case":"09","in_dialogue":true,"learning_status":"active"},{"term":"cangri","meaning":"An important, influential person (noun); extraordinary or excellent (adjective). These are two recorded Puerto Rican youth senses, not a universal title for any singer.","region_and_use":"Puerto Rico. RECOGNISE FIRST.","spanish_example":"En ese grupo, Luis es el cangri.","english_example":"In that group, Luis is the influential figure.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/cangri","case":"07","in_dialogue":false,"learning_status":"recognition"},{"term":"caserío","meaning":"A government-subsidised apartment complex in the Puerto Rican sense. General Spanish has other settlement-related senses. The word is not a judgement about residents.","region_and_use":"Puerto Rico, selected housing sense. CULTURAL RECOGNITION.","spanish_example":"El centro de música está cerca del caserío.","english_example":"The music centre is near the public-housing complex.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/caser%C3%ADo","case":"07","in_dialogue":false,"learning_status":"active"},{"term":"chamaquito / chamaquita","meaning":"Small child or adolescent in the recorded regional use; precise age and tone depend on the situation.","region_and_use":"Mexico, Nicaragua, Dominican Republic, Puerto Rico. RECOGNISE FIRST.","spanish_example":"El chamaquito preguntó cuándo empezaba la música.","english_example":"The child asked when the music would begin.","find_it":"Case 02. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/chamaquito","case":"02","in_dialogue":false,"learning_status":"recognition"},{"term":"chatear","meaning":"To chat online in the digital sense; the separate Spanish drinking sense is not taught here.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Vamos a chatear mañana.","english_example":"Let's chat online tomorrow.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/chatear","case":"04","in_dialogue":false,"learning_status":"active"},{"term":"chavos","meaning":"Money, in the plural sense taught here. Singular chavo and forms in other countries have additional meanings.","region_and_use":"Cuba, Dominican Republic, Puerto Rico. RECOGNISE FIRST.","spanish_example":"¿Tienes chavos para el pasaje?","english_example":"Do you have money for the fare?","find_it":"Case 09. Dialogue: Case 09, Case 12.","sources":"https://www.asale.org/damer/chavo","case":"09","in_dialogue":true,"learning_status":"recognition"},{"term":"chévere","meaning":"Very good or excellent when describing a thing; friendly or pleasant when describing a person in documented senses. The distributions differ by sense.","region_and_use":"many American varieties, including Puerto Rico; see the cited sense. CONTEXT DEPENDENT.","spanish_example":"La música está chévere.","english_example":"The music is great.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/ch%C3%A9vere","case":"04","in_dialogue":false,"learning_status":"context"},{"term":"claro","meaning":"Of course in a reply; clear as an adjective in other contexts.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Claro, puedo ayudarte.","english_example":"Of course, I can help you.","find_it":"Case 01. Dialogue: Case 01, Case 02, Case 03, Case 04, Case 06, Case 07, Case 10, Case 11.","sources":"https://dle.rae.es/claro","case":"01","in_dialogue":true,"learning_status":"active"},{"term":"concierto","meaning":"Concert in the performance sense.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Después del concierto nos vemos.","english_example":"We'll see each other after the concert.","find_it":"Case 09. Dialogue: Case 08, Case 09.","sources":"https://dle.rae.es/concierto","case":"09","in_dialogue":true,"learning_status":"active"},{"term":"conocer","meaning":"To meet or get to know a person; also to know through acquaintance.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Quiero conocer a tu grupo.","english_example":"I want to meet your group.","find_it":"Case 02. Dialogue: Case 02.","sources":"https://dle.rae.es/conocer","case":"02","in_dialogue":true,"learning_status":"active"},{"term":"corillo","meaning":"A lively group of young people in ASALE; a group of friends or crew in the Puerto Rican usage guide and these scenes. It does not inherently mean a criminal gang.","region_and_use":"Puerto Rico. RECOGNISE FIRST.","spanish_example":"Mi corillo hace música.","english_example":"My group of friends makes music.","find_it":"Case 02. Dialogue: Case 02, Case 07, Case 12.","sources":"https://www.asale.org/damer/corillo ; https://www.discoverpuertorico.com/article/puerto-ricos-reggaeton-slang-explained","case":"02","in_dialogue":true,"learning_status":"recognition"},{"term":"¿cuánto cuesta?","meaning":"How much does it cost? Use cuestan for a plural subject.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Cuánto cuesta el café?","english_example":"How much is the coffee?","find_it":"Case 09. Dialogue: Case 09, Case 12.","sources":"https://dle.rae.es/costar","case":"09","in_dialogue":true,"learning_status":"active"},{"term":"cuartos","meaning":"Money in the Dominican sense used here. Cuarto also means a room and has further meanings; the surrounding sentence matters.","region_and_use":"Dominican Republic, money sense. RECOGNISE FIRST.","spanish_example":"Hoy no tengo cuartos para el café.","english_example":"I don't have money for coffee today.","find_it":"Case 09. Dialogue: Case 09.","sources":"https://www.asale.org/damer/cuarto","case":"09","in_dialogue":true,"learning_status":"recognition"},{"term":"dale","meaning":"Okay, go ahead or an encouragement to proceed, according to the exchange. It is also a form of dar in other constructions.","region_and_use":"informal conversation across several varieties; not uniquely Puerto Rican. CONTEXT DEPENDENT.","spanish_example":"Dale, pon la grabación.","english_example":"Go ahead, play the recording.","find_it":"Case 04. Dialogue: Case 01, Case 03, Case 04, Case 05, Case 11, Case 12.","sources":"https://www.asale.org/damer/dar","case":"04","in_dialogue":true,"learning_status":"context"},{"term":"de una","meaning":"Immediately or without delay in the cited locution; this source does not establish every use meaning agreement.","region_and_use":"Colombia, Venezuela, Ecuador, Paraguay. RECOGNISE FIRST.","spanish_example":"Empezamos de una.","english_example":"We start right away.","find_it":"Case 04. Dialogue: Case 10.","sources":"https://www.asale.org/damer/una","case":"04","in_dialogue":true,"learning_status":"recognition"},{"term":"dejar en visto","meaning":"To leave a message marked as read without replying; not necessarily sustained ghosting or evidence of hostility.","region_and_use":"digital informal usage; cited Fundéu discussion mentions Mexico and Colombia. CONTEXT DEPENDENT.","spanish_example":"Luis me dejó en visto, pero respondió más tarde.","english_example":"Luis left me on read, but replied later.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.fundeu.es/blog/por-que-esfumarse-cuando-puedes-hacer-ghosting/","case":"04","in_dialogue":false,"learning_status":"context"},{"term":"dembow","meaning":"A characteristic rhythmic pattern or family associated with reggaeton; also a Dominican urban music genre. Distinguish the rhythm from the genre and from a generic beat.","region_and_use":"Caribbean music history; Dominican genre sense. MUSIC RECOGNITION.","spanish_example":"Comparamos el patrón de dembow con otros ritmos.","english_example":"We compare the dembow pattern with other rhythms.","find_it":"Case 05. Dialogue: Case 05, Case 12.","sources":"https://college.berklee.edu/songwriting/news/what-is-dembow-tracing-the-roots-of-a-global-phenomenon","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"después de","meaning":"After, followed by the event or thing. De + el combines as del.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Después del ensayo, vamos al café.","english_example":"After the rehearsal, let's go to the café.","find_it":"Case 11. Dialogue: Case 05, Case 11, Case 12.","sources":"https://dle.rae.es/despu%C3%A9s","case":"11","in_dialogue":true,"learning_status":"active"},{"term":"dinero","meaning":"Money.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Tienes dinero?","english_example":"Do you have any money?","find_it":"Case 09. Dialogue: Case 09.","sources":"https://dle.rae.es/dinero","case":"09","in_dialogue":true,"learning_status":"active"},{"term":"duro / dura","meaning":"Hard or difficult in general Spanish; very skilled or highly prepared when describing a person in selected regional senses. Other senses include attractive, so the referent matters.","region_and_use":"skilled-person senses: Dominican Republic, Puerto Rico, Venezuela, Ecuador; further senses elsewhere. CONTEXT DEPENDENT.","spanish_example":"Luis es un duro en producción musical.","english_example":"Luis is highly skilled in music production.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/duro","case":"07","in_dialogue":false,"learning_status":"context"},{"term":"en el estudio","meaning":"In the studio in the recording context; estudio has other study/apartment senses.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Nora está en el estudio.","english_example":"Nora is in the studio.","find_it":"Case 05. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/estudio","case":"05","in_dialogue":false,"learning_status":"active"},{"term":"enamorarse","meaning":"To fall in love; compare enamorar, to make someone fall in love.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"No quiero enamorarme tan rápido.","english_example":"I don't want to fall in love so quickly.","find_it":"Case 08. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/enamorar","case":"08","in_dialogue":false,"learning_status":"active"},{"term":"estar listo / lista","meaning":"To be ready; listo can also mean clever, especially with ser.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Ya está lista la pista?","english_example":"Is the track ready yet?","find_it":"Case 12. Dialogue: Case 01, Case 11, Case 12.","sources":"https://dle.rae.es/listo","case":"12","in_dialogue":true,"learning_status":"active"},{"term":"estribillo","meaning":"Chorus or refrain, a recurring section or line of a song.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"El estribillo vuelve al final.","english_example":"The chorus comes back at the end.","find_it":"Case 05. Dialogue: Case 05, Case 10, Case 12.","sources":"https://dle.rae.es/estribillo","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"fama","meaning":"Fame in the recognition/popularity sense; reputation in other sentences.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"La fama no explica todo.","english_example":"Fame doesn't explain everything.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/fama","case":"07","in_dialogue":false,"learning_status":"active"},{"term":"feca","meaning":"A lie or deception in the Puerto Rican sense; not simply the English adjective fake. In Chile the word has unrelated excrement/poor-quality senses.","region_and_use":"Puerto Rico, selected lie sense. RECOGNISE FIRST.","spanish_example":"Eso es feca; no pasó así.","english_example":"That's a lie; it didn't happen that way.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/feca","case":"07","in_dialogue":false,"learning_status":"recognition"},{"term":"fiesta","meaning":"Party or celebration in the social-event sense.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"La fiesta empieza a las ocho.","english_example":"The party starts at eight.","find_it":"Case 03. Dialogue: Case 03.","sources":"https://dle.rae.es/fiesta","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"flow","meaning":"Rhythmic and articulatory delivery of words over music in this lesson. Broader style-related uses need their own context.","region_and_use":"music terminology, English borrowing. CONTEXT DEPENDENT.","spanish_example":"El beat es el mismo, pero el flow cambió.","english_example":"The beat is the same, but the flow changed.","find_it":"Case 05. Dialogue: Case 05, Case 12.","sources":"https://mtosmt.org/issues/mto.17.23.4/mto.17.23.4.komaniecki.html","case":"05","in_dialogue":true,"learning_status":"context"},{"term":"frontear","meaning":"To boast or show off in the recorded Puerto Rican informal youth sense. An accusation does not prove the judgement is fair.","region_and_use":"Puerto Rico. RECOGNISE FIRST.","spanish_example":"No quiero frontear.","english_example":"I don't want to show off.","find_it":"Case 07. Dialogue: Case 07, Case 12.","sources":"https://www.asale.org/damer/frontear","case":"07","in_dialogue":true,"learning_status":"recognition"},{"term":"genial","meaning":"Great or excellent in a positive everyday evaluation.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¡Qué genial quedó el cartel!","english_example":"The poster turned out great!","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/genial","case":"04","in_dialogue":false,"learning_status":"active"},{"term":"grabar","meaning":"To record sound or images in the selected sense.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Vamos a grabar una escena.","english_example":"Let's record a scene.","find_it":"Case 05. Dialogue: Case 04, Case 05, Case 07, Case 11.","sources":"https://dle.rae.es/grabar","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"guagua","meaning":"Bus in Cuba, the Dominican Republic, Puerto Rico and further recorded locations; infant or young child in several South American areas, including Chile. These are separate senses.","region_and_use":"sense-specific Caribbean and South American labels. RECOGNISE FIRST.","spanish_example":"La guagua duerme en su cuna.","english_example":"The baby sleeps in its cot/crib.","find_it":"Case 10. Dialogue: Case 10, Case 12.","sources":"https://www.asale.org/damer/guagua","case":"10","in_dialogue":true,"learning_status":"recognition"},{"term":"guayar","meaning":"To grate in recorded Dominican/Puerto Rican senses; to scratch a surface in another PR sense. The separate PR expression guayar la hebilla means to dance very close to a partner.","region_and_use":"Dominican Republic and Puerto Rico for grating; Puerto Rico for the dance expression. CONTEXT DEPENDENT; DANCE EXPRESSION IS ADULT CONTEXT.","spanish_example":"Voy a guayar el queso.","english_example":"I am going to grate the cheese.","find_it":"Case 06. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/guayar","case":"06","in_dialogue":false,"learning_status":"recognition_sensitive"},{"term":"hacer un plan","meaning":"To make a plan.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Vamos a hacer un plan.","english_example":"Let's make a plan.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/plan","case":"03","in_dialogue":false,"learning_status":"active"},{"term":"hermano / hermana","meaning":"Brother or sister in the family sense; familiar address has a different social use.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Mi hermano vive cerca.","english_example":"My brother lives nearby.","find_it":"Case 02. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/hermano","case":"02","in_dialogue":false,"learning_status":"active"},{"term":"hola","meaning":"Hello, a familiar greeting.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Hola, Luis.","english_example":"Hello, Luis.","find_it":"Case 01. Dialogue: Case 04.","sources":"https://dle.rae.es/hola","case":"01","in_dialogue":true,"learning_status":"active"},{"term":"ignorar","meaning":"To ignore in the attention-related sense; also not to know something in another sense.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"No quiero ignorar el mensaje.","english_example":"I don't want to ignore the message.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/ignorar","case":"04","in_dialogue":false,"learning_status":"active"},{"term":"invitar","meaning":"To invite someone to an event, or pay for someone as a treat; distinguish by context.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Hoy invito yo.","english_example":"It's my treat today.","find_it":"Case 03. Dialogue: Case 03, Case 09.","sources":"https://dle.rae.es/invitar","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"janguear","meaning":"Go out for enjoyment or socialise in the Puerto Rican sense; a separate US sense includes having fun or being unoccupied. The venue is not fixed by the verb.","region_and_use":"Puerto Rico; separate US sense. RECOGNISE FIRST.","spanish_example":"¿Quieres janguear el sábado?","english_example":"Do you want to hang out on Saturday?","find_it":"Case 03. Dialogue: Case 03, Case 12.","sources":"https://www.asale.org/damer/janguear","case":"03","in_dialogue":true,"learning_status":"recognition"},{"term":"jangueo","meaning":"Social enjoyment through conversation, jokes and time with companions, for example in a café or street; a get-together in the teaching scene.","region_and_use":"Puerto Rico. RECOGNISE FIRST.","spanish_example":"Es un jangueo tranquilo en el café.","english_example":"It's a relaxed get-together at the café.","find_it":"Case 03. Dialogue: Case 03.","sources":"https://www.asale.org/damer/jangueo","case":"03","in_dialogue":true,"learning_status":"recognition"},{"term":"jeva","meaning":"Girlfriend in colloquial Puerto Rican usage documented by the University of Houston project glossary. ASALE separately records young-woman senses in several countries, girlfriend in Honduras and a sex-worker sense for Puerto Rico; jeba has further senses. Context determines the reading.","region_and_use":"Puerto Rico: colloquial girlfriend in the university glossary; other senses have separate ASALE country labels. COLLOQUIAL RELATIONSHIP WORD; OTHER SENSES MAY BE DEROGATORY — RECOGNISE FIRST.","spanish_example":"Nora leyó «jeva» y preguntó de qué país era el comentario.","english_example":"Nora read “jeva” and asked which country the comment came from.","find_it":"Case 08. Dialogue: Case 08.","sources":"https://www.asale.org/damer/jeva ; https://www.asale.org/damer/jeba ; https://plpr.uh.edu/s/es/page/glosario","case":"08","in_dialogue":true,"learning_status":"recognition_sensitive"},{"term":"jevo","meaning":"Boyfriend in colloquial Puerto Rican usage documented by the University of Houston project glossary. ASALE lists jevo, -a for boyfriend/girlfriend in additional specified youth uses.","region_and_use":"Puerto Rico (university glossary); Nicaragua, Cuba, Dominican Republic, Venezuela, Peru (ASALE youth label). COLLOQUIAL — RECOGNISE FIRST.","spanish_example":"En el ejemplo dominicano, «mi jevo» se refiere al novio.","english_example":"In the Dominican example, “mi jevo” refers to the boyfriend.","find_it":"Case 08. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/jevo ; https://plpr.uh.edu/s/es/page/glosario","case":"08","in_dialogue":false,"learning_status":"recognition"},{"term":"klk","meaning":"Informal chat abbreviation of the familiar Dominican greeting ¿qué lo que?; not a formal contraction or an all-country greeting.","region_and_use":"Dominican Republic; contemporary local essay, 2026. RECOGNISE FIRST — DIGITAL.","spanish_example":"Luis recibió un saludo escrito así: «klk».","english_example":"Luis received a greeting written as “klk”.","find_it":"Case 01. Supplementary; not spoken in a main dialogue.","sources":"https://esendom.com/cultura//26-cosas-dominicanas/dime-a-ve-que-lo-que","case":"01","in_dialogue":false,"learning_status":"recognition"},{"term":"la banda","meaning":"The musical band in this example; other group senses exist.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"La banda ensaya el sábado.","english_example":"The band rehearses on Saturday.","find_it":"Case 02. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/banda","case":"02","in_dialogue":false,"learning_status":"active"},{"term":"llamada","meaning":"Call, including a phone call in the example.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Tengo una llamada a las cinco.","english_example":"I have a call at five.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/llamada","case":"04","in_dialogue":false,"learning_status":"active"},{"term":"mamey","meaning":"A fruit/tree in several countries. Separately, an easy task or thing in PR; easy as an adjective in Colombia. PR also has a profitable-job sense. Other countries record vulgar sexual senses, so do not transfer the easy meaning indiscriminately.","region_and_use":"Puerto Rico and Colombia for the distinct easy senses; fruit and other senses more widely. CONTEXT DEPENDENT — OTHER SENSES CAN BE VULGAR.","spanish_example":"Para Nora, ese ejercicio es un mamey.","english_example":"For Nora, that exercise is really easy.","find_it":"Case 10. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/mamey","case":"10","in_dialogue":false,"learning_status":"recognition_sensitive"},{"term":"mandar un mensaje","meaning":"To send a message.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Voy a mandar un mensaje.","english_example":"I'm going to send a message.","find_it":"Case 04. Dialogue: Case 04.","sources":"https://dle.rae.es/mandar","case":"04","in_dialogue":true,"learning_status":"active"},{"term":"me encanta","meaning":"I love or really like the following thing/activity; not necessarily romantic love.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Me encanta el ritmo.","english_example":"I love the rhythm.","find_it":"Case 05. Dialogue: Case 05.","sources":"https://dle.rae.es/encantar","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"me gusta","meaning":"I like the following singular thing or activity; plural things take me gustan.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Me gusta la música.","english_example":"I like music.","find_it":"Case 08. Dialogue: Case 02, Case 07, Case 08, Case 10, Case 11.","sources":"https://dle.rae.es/gustar","case":"08","in_dialogue":true,"learning_status":"active"},{"term":"me gustas","meaning":"I like you; often implies personal attraction, unlike liking an activity.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Me gustas tú.","english_example":"I like you.","find_it":"Case 08. Dialogue: Case 08.","sources":"https://dle.rae.es/gustar","case":"08","in_dialogue":true,"learning_status":"active"},{"term":"meneo","meaning":"Movement, swaying or shaking in this example; not exclusively musical or erotic.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"El meneo de la coreografía sigue el ritmo.","english_example":"The movement in the choreography follows the rhythm.","find_it":"Case 06. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/meneo","case":"06","in_dialogue":false,"learning_status":"active"},{"term":"mensaje","meaning":"Message, including a written digital message.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Te llegó mi mensaje?","english_example":"Did you get my message?","find_it":"Case 04. Dialogue: Case 04, Case 08, Case 09, Case 10, Case 11.","sources":"https://dle.rae.es/mensaje","case":"04","in_dialogue":true,"learning_status":"active"},{"term":"mi gente","meaning":"My people/my crowd; an informal collective address in this example, not necessarily my family.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Gracias, mi gente.","english_example":"Thanks, everyone!","find_it":"Case 02. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/gente","case":"02","in_dialogue":false,"learning_status":"active"},{"term":"mofongo","meaning":"A dish based on mashed green plantains, traditionally with fried pork or bacon, salt and garlic in ASALE; preparations can differ.","region_and_use":"Puerto Rico and Dominican Republic. FOOD / CULTURAL VOCABULARY.","spanish_example":"Hoy comemos mofongo.","english_example":"We're eating mofongo today.","find_it":"Case 10. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/mofongo","case":"10","in_dialogue":false,"learning_status":"active"},{"term":"mucho gusto","meaning":"Nice to meet you, as an introductory expression in this example.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Mucho gusto, Nora.","english_example":"Nice to meet you, Nora.","find_it":"Case 02. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/gusto","case":"02","in_dialogue":false,"learning_status":"active"},{"term":"música","meaning":"Music; a general word, not a slang invention.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Me gusta la música.","english_example":"I like music.","find_it":"Case 02. Dialogue: Case 01, Case 02, Case 03, Case 05, Case 06, Case 07, Case 08, Case 09, Case 10, Case 11, Case 12.","sources":"https://dle.rae.es/m%C3%BAsica","case":"02","in_dialogue":true,"learning_status":"active"},{"term":"no necesariamente","meaning":"Not necessarily; a useful response to an assumption.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"No necesariamente queremos bailar.","english_example":"We don't necessarily want to dance.","find_it":"Case 03. Dialogue: Case 03.","sources":"https://dle.rae.es/necesariamente","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"no pasa nada","meaning":"It's okay or no problem in a reassuring response; the literal sentence can also mean nothing is happening.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"No pasa nada. Te respondo luego.","english_example":"No problem. I'll reply later.","find_it":"Case 01. Dialogue: Case 01.","sources":"https://dle.rae.es/pasar","case":"01","in_dialogue":true,"learning_status":"active"},{"term":"nos vemos","meaning":"See you as a leave-taking; we see/meet each other in other constructions.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Nos vemos mañana.","english_example":"See you tomorrow.","find_it":"Case 01. Dialogue: Case 03, Case 09.","sources":"https://dle.rae.es/ver","case":"01","in_dialogue":true,"learning_status":"active"},{"term":"novio / novia","meaning":"Boyfriend/girlfriend in a romantic relationship; fiancé/fiancée or bride/groom in other contexts.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Mi novia viene al concierto.","english_example":"My girlfriend is coming to the concert.","find_it":"Case 08. Dialogue: Case 08.","sources":"https://dle.rae.es/novio","case":"08","in_dialogue":true,"learning_status":"active"},{"term":"nuestro grupo","meaning":"Our group; nuestra is needed before a feminine singular noun, such as música.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Nuestro grupo hace música.","english_example":"Our group makes music.","find_it":"Case 02. Dialogue: Case 02.","sources":"https://dle.rae.es/nuestro","case":"02","in_dialogue":true,"learning_status":"active"},{"term":"orgulloso / orgullosa","meaning":"Proud; the example expresses satisfaction in a team rather than arrogance.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Estoy orgulloso del equipo.","english_example":"I'm proud of the team.","find_it":"Case 07. Dialogue: Case 07, Case 12.","sources":"https://dle.rae.es/orgulloso","case":"07","in_dialogue":true,"learning_status":"active"},{"term":"pa","meaning":"Pa is an informal shortening of para. The independent shortening takes no apostrophe under DPD guidance. Pa’ is an encountered non-standard spelling; contractions between words, such as pa'l, are a different case.","region_and_use":"informal Spanish; no exclusive regional claim. RECOGNISE FIRST — INFORMAL WRITING.","spanish_example":"Vamos pa casa.","english_example":"We're going home.","find_it":"Case 11. Dialogue: Case 11.","sources":"https://www.rae.es/dpd/ap%C3%B3strofo","case":"11","in_dialogue":true,"learning_status":"recognition"},{"term":"pana","meaning":"Close friend or buddy in the selected sense. Other meanings include breadfruit in PR/RD and a mechanical breakdown in Chile.","region_and_use":"Puerto Rico and numerous other American varieties, sense-specific. RECOGNISE FIRST.","spanish_example":"Luis es mi pana.","english_example":"Luis is a close friend of mine.","find_it":"Case 01. Dialogue: Case 01, Case 02, Case 12.","sources":"https://www.asale.org/damer/pana","case":"01","in_dialogue":true,"learning_status":"recognition"},{"term":"para","meaning":"For, to or towards depending on structure; used for a purpose, recipient or destination.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Esta canción es para mis amigos.","english_example":"This song is for my friends.","find_it":"Case 11. Dialogue: Case 02, Case 03, Case 04, Case 05, Case 06, Case 08, Case 09, Case 10, Case 11, Case 12.","sources":"https://dle.rae.es/para","case":"11","in_dialogue":true,"learning_status":"active"},{"term":"parce","meaning":"A shortened form of parcero used as familiar address among known young people in the cited record.","region_and_use":"Colombia and Ecuador. RECOGNISE FIRST.","spanish_example":"Parce, ¿cómo estás?","english_example":"My friend, how are you?","find_it":"Case 10. Dialogue: Case 10.","sources":"https://www.asale.org/damer/parce ; https://www.asale.org/damer/parcero","case":"10","in_dialogue":true,"learning_status":"recognition"},{"term":"parcero / parcera","meaning":"A close friend; also a familiar address. See parce for the shortened address, not a different universal friendship category.","region_and_use":"Colombia and Ecuador. RECOGNISE FIRST.","spanish_example":"Mi parcera viene al concierto.","english_example":"My friend is coming to the concert.","find_it":"Case 10. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/parcero","case":"10","in_dialogue":false,"learning_status":"recognition"},{"term":"pareja","meaning":"Partner, pair or couple depending on context; specify romantic or dance partnership if needed.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Mi pareja escucha música conmigo.","english_example":"My partner listens to music with me.","find_it":"Case 08. Dialogue: Case 08.","sources":"https://dle.rae.es/pareja","case":"08","in_dialogue":true,"learning_status":"active"},{"term":"pasar el rato","meaning":"To spend time, usually with some entertainment; hang out in the café example.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Vamos a pasar el rato en el café.","english_example":"Let's spend some time together at the café.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/rato","case":"03","in_dialogue":false,"learning_status":"active"},{"term":"perrear","meaning":"To dance perreo in the selected music/dance sense, also recorded in the DLE. ASALE records unrelated meanings such as flirting, belittling or flattering in different countries.","region_and_use":"dance sense in general lexicography and several American varieties, including Puerto Rico; other senses have separate labels. ADULT DANCE CONTEXT — RECOGNISE FIRST.","spanish_example":"Nora preguntó si el evento incluía perrear.","english_example":"Nora asked whether the event included dancing perreo.","find_it":"Case 06. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/perrear ; https://dle.rae.es/perrear","case":"06","in_dialogue":false,"learning_status":"recognition_sensitive"},{"term":"perreo","meaning":"A dance usually associated with reggaeton and sensual hip movement. The DLE describes a common position when danced in pairs; ASALE describes close partner dancing. The name does not require every performance to use a pair.","region_and_use":"general music/dance term also recorded across American varieties including Puerto Rico; source labels vary by sense. ADULT DANCE CONTEXT — RECOGNISE FIRST.","spanish_example":"El programa incluye una explicación del perreo.","english_example":"The programme includes an explanation of perreo.","find_it":"Case 06. Dialogue: Case 06, Case 12.","sources":"https://www.asale.org/damer/perreo ; https://dle.rae.es/perreo","case":"06","in_dialogue":true,"learning_status":"recognition_sensitive"},{"term":"peso","meaning":"A currency unit used in various countries; not the currency unit of Puerto Rico.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Cuesta cien pesos.","english_example":"It costs a hundred pesos.","find_it":"Case 09. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/peso","case":"09","in_dialogue":false,"learning_status":"active"},{"term":"pichear","meaning":"Ignore or disregard in the Puerto Rican informal social sense. Separately, pitch a baseball in ASALE. The sports entry is not evidence for the ignore sense.","region_and_use":"Puerto Rico for the selected informal sense; baseball more widely. RECOGNISE FIRST.","spanish_example":"No me pichees; necesito saber si vienes.","english_example":"Don't ignore me; I need to know whether you're coming.","find_it":"Case 04. Dialogue: Case 04.","sources":"https://www.maiasherwood.com/escritos/no-me-picheen ; https://www.discoverpuertorico.com/article/puerto-ricos-reggaeton-slang-explained","case":"04","in_dialogue":true,"learning_status":"recognition"},{"term":"pista","meaning":"Track in a recording/music discussion; clue in a different context. A complete recording and an individual recording channel are not always the same thing.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Escuchamos la pista nueva.","english_example":"We listen to the new track.","find_it":"Case 05. Dialogue: Case 05, Case 06, Case 10, Case 12.","sources":"https://dle.rae.es/pista","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"plata","meaning":"Money or wealth in many American varieties; also silver. Do not assign the money meaning to every context or label it exclusively PR.","region_and_use":"many American varieties; source lists the distribution. CONTEXT DEPENDENT.","spanish_example":"No tengo plata para la entrada.","english_example":"I don't have money for the ticket.","find_it":"Case 09. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/plata","case":"09","in_dialogue":false,"learning_status":"context"},{"term":"podemos","meaning":"We can, the nosotros/nosotras present form of poder; followed by an infinitive in the example.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Podemos vernos a las cuatro.","english_example":"We can meet at four.","find_it":"Case 03. Dialogue: Case 02, Case 03, Case 05, Case 06, Case 08, Case 11, Case 12.","sources":"https://dle.rae.es/poder","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"presumir","meaning":"To boast or show off in this sense; it can mean to suppose in another construction.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"No quiero presumir.","english_example":"I don't want to boast.","find_it":"Case 07. Dialogue: Case 07.","sources":"https://dle.rae.es/presumir","case":"07","in_dialogue":true,"learning_status":"active"},{"term":"qué bolá","meaning":"A familiar greeting among people who know one another, approximately what's up?.","region_and_use":"Cuba. RECOGNISE FIRST.","spanish_example":"¿Qué bolá, Nora? —Todo bien.","english_example":"What's up, Nora? —All good.","find_it":"Case 01. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/bol%C3%A1","case":"01","in_dialogue":false,"learning_status":"recognition"},{"term":"¿qué es la que hay?","meaning":"A familiar greeting in the Puerto Rican use discussed by Sherwood Droz, approximately what's up? The shorter ¿Qué es la que? is also documented.","region_and_use":"Puerto Rico; descriptive column, not a current frequency survey. RECOGNISE FIRST.","spanish_example":"¿Qué es la que hay, Luis?","english_example":"What's up, Luis?","find_it":"Case 01. Dialogue: Case 01, Case 12.","sources":"https://www.maiasherwood.com/escritos/qu-es-la-que","case":"01","in_dialogue":true,"learning_status":"recognition"},{"term":"¿qué pasa?","meaning":"What is happening or what is wrong? With con, it may ask what about a particular matter; read the complete question.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Qué pasa con la grabación?","english_example":"What is happening with the recording?","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/pasar","case":"04","in_dialogue":false,"learning_status":"active"},{"term":"¿qué significa?","meaning":"What does it mean?.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Qué significa esta palabra?","english_example":"What does this word mean?","find_it":"Case 10. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/significar","case":"10","in_dialogue":false,"learning_status":"active"},{"term":"responder","meaning":"To reply or answer.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Voy a responder al mensaje.","english_example":"I'm going to reply to the message.","find_it":"Case 04. Dialogue: Case 04, Case 10.","sources":"https://dle.rae.es/responder","case":"04","in_dialogue":true,"learning_status":"active"},{"term":"riddim","meaning":"A Jamaican reggae/dancehall rhythm track or backing that can be used for different recordings; not the same as vocal flow.","region_and_use":"Jamaican music terminology in the musical history discussion. MUSIC RECOGNITION.","spanish_example":"El productor trabajó con el mismo riddim.","english_example":"The producer worked with the same riddim.","find_it":"Case 05. Supplementary; not spoken in a main dialogue.","sources":"https://college.berklee.edu/songwriting/news/what-is-dembow-tracing-the-roots-of-a-global-phenomenon","case":"05","in_dialogue":false,"learning_status":"active"},{"term":"ritmo","meaning":"Rhythm; it may describe a beat without making every music term interchangeable.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Me gusta este ritmo.","english_example":"I like this rhythm.","find_it":"Case 05. Dialogue: Case 03, Case 05, Case 06, Case 07.","sources":"https://dle.rae.es/ritmo","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"rumba","meaning":"Party in the selected informal sense across several American varieties; separately, an Afro-Cuban musical genre. Do not treat the party gloss as the definition of the genre.","region_and_use":"party sense widely recorded in the Americas; music sense associated with Cuba. CONTEXT DEPENDENT.","spanish_example":"Vamos a una rumba.","english_example":"We're going to a party.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/rumba","case":"03","in_dialogue":false,"learning_status":"context"},{"term":"salir","meaning":"To go out or leave, according to the destination and situation.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"¿Quieres salir el sábado?","english_example":"Do you want to go out on Saturday?","find_it":"Case 03. Dialogue: Case 03, Case 07, Case 08.","sources":"https://dle.rae.es/salir","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"sandungueo","meaning":"Hip movement when walking or dancing in one recorded sense; separately, participation and enjoyment in a lively party. It does not automatically name a sexual act.","region_and_use":"movement: Honduras (north), Nicaragua, Cuba, Puerto Rico, Chile; party: Puerto Rico, Peru, Chile. RECOGNISE FIRST.","spanish_example":"El sandungueo de Luis sigue el ritmo.","english_example":"Luis's hip movement follows the rhythm.","find_it":"Case 06. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/sandungueo","case":"06","in_dialogue":false,"learning_status":"recognition"},{"term":"seguir el ritmo","meaning":"To follow or keep to the beat.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Sigue el ritmo.","english_example":"Follow the beat.","find_it":"Case 06. Dialogue: Case 06.","sources":"https://dle.rae.es/seguir","case":"06","in_dialogue":true,"learning_status":"active"},{"term":"sisas","meaning":"Yes, in the recorded Colombian youth usage.","region_and_use":"Colombia. RECOGNISE FIRST.","spanish_example":"¿Vienes al concierto? —Sisas.","english_example":"Are you coming to the concert? —Yes.","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/sisas","case":"04","in_dialogue":false,"learning_status":"recognition"},{"term":"socio / socia","meaning":"Business partner or associate in this example; friendly address is a separate contextual use.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Mi socio trabaja conmigo.","english_example":"My business partner works with me.","find_it":"Case 02. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/socio","case":"02","in_dialogue":false,"learning_status":"active"},{"term":"subir / bajar","meaning":"Turn up/down when the object is volume; raise/lower or go up/down in other contexts.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Sube el volumen un poco y luego bájalo.","english_example":"Turn the volume up a little, then turn it down.","find_it":"Case 05. Dialogue: Case 05.","sources":"https://dle.rae.es/subir ; https://dle.rae.es/bajar","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"tarima","meaning":"Raised platform or stage in the event context; PR entries include a podium or unrailed platform. Other senses exist elsewhere.","region_and_use":"general platform; region-specific senses including Puerto Rico. MUSIC / EVENT VOCABULARY.","spanish_example":"La tarima está lista.","english_example":"The stage is ready.","find_it":"Case 05. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/tarima","case":"05","in_dialogue":false,"learning_status":"active"},{"term":"te escribo","meaning":"I'll write/message you in a future-oriented context; I write to you in another context.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Te escribo esta noche.","english_example":"I'll text you tonight.","find_it":"Case 03. Dialogue: Case 03.","sources":"https://dle.rae.es/escribir","case":"03","in_dialogue":true,"learning_status":"active"},{"term":"tema","meaning":"Song or track in this music use; topic or theme in other contexts.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Escucha este tema nuevo.","english_example":"Listen to this new song.","find_it":"Case 05. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/tema","case":"05","in_dialogue":false,"learning_status":"active"},{"term":"tengo tiempo","meaning":"I have time; it does not mean just a minute.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Tengo tiempo por la tarde.","english_example":"I have time in the afternoon.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://dle.rae.es/tiempo","case":"03","in_dialogue":false,"learning_status":"active"},{"term":"teteo","meaning":"Party or social gathering in the Dominican informal context exemplified by the cited report. That report concerns a noisy gathering; it does not establish that every teteo is illegal.","region_and_use":"Dominican Republic; journalistic attestation, 2024. RECOGNISE FIRST.","spanish_example":"Después del ensayo, hablaron de un teteo.","english_example":"After the rehearsal, they talked about a party.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://www.diariolibre.com/actualidad/ciudad/2024/11/01/teteo-en-ciudad-nueva-roba-la-tranquildad-de-residentes/2899003","case":"03","in_dialogue":false,"learning_status":"recognition"},{"term":"tíguere","meaning":"A brazen, audacious or disreputable person, usually young, in one Dominican sense; another Dominican sense leaves identity unspecified. It is not an automatic compliment meaning cool.","region_and_use":"Dominican Republic, selected person senses; PR also records tiger. POTENTIALLY DEROGATORY — RECOGNISE FIRST.","spanish_example":"Luis oyó «tíguere» y preguntó si era una crítica.","english_example":"Luis heard “tíguere” and asked whether it was a criticism.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/t%C3%ADguere","case":"07","in_dialogue":false,"learning_status":"recognition_sensitive"},{"term":"tiraera","meaning":"A lyrical diss or musical challenge in Puerto Rican reggaeton discussion; not a general synonym for every argument.","region_and_use":"Puerto Rican music context. RECOGNISE FIRST.","spanish_example":"Luis escuchó una tiraera y preguntó a quién iba dirigida.","english_example":"Luis heard a lyrical diss and asked who it was aimed at.","find_it":"Case 07. Supplementary; not spoken in a main dialogue.","sources":"https://www.discoverpuertorico.com/article/puerto-ricos-reggaeton-slang-explained","case":"07","in_dialogue":false,"learning_status":"recognition"},{"term":"todo bien","meaning":"All good/everything is fine in the greeting reply.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"Todo bien, ¿y tú?","english_example":"All good. And you?","find_it":"Case 01. Dialogue: Case 01.","sources":"https://dle.rae.es/bien","case":"01","in_dialogue":true,"learning_status":"active"},{"term":"tusa","meaning":"Heartache or resentment after romantic disappointment in the recorded western Colombian sense. The spelling has unrelated meanings elsewhere.","region_and_use":"western Colombia, selected romantic sense. RECOGNISE FIRST.","spanish_example":"Después de la ruptura, Nora tenía tusa.","english_example":"After the breakup, Nora was heartbroken.","find_it":"Case 08. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/tusa","case":"08","in_dialogue":false,"learning_status":"recognition"},{"term":"vacilar","meaning":"To hesitate in general Spanish; to enjoy oneself in colloquial senses recorded by the DLE for Colombia, Costa Rica, Cuba, Guatemala and Puerto Rico; to dance in some ASALE regional senses; to deceive or tease in other constructions. Choose by the sentence.","region_and_use":"each sense has its own regional distribution. CONTEXT DEPENDENT.","spanish_example":"Luis vacila entre dos canciones.","english_example":"Luis hesitates between two songs.","find_it":"Case 03. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/vacilar ; https://dle.rae.es/vacilar","case":"03","in_dialogue":false,"learning_status":"context"},{"term":"vaina","meaning":"Thing or matter whose name is unknown, forgotten or deliberately left unspecified, in recorded American varieties. The source marks this sense vulgar in Venezuela and records further sensitive meanings.","region_and_use":"many American varieties, including Dominican Republic; labels differ by sense/region. CONTEXT DEPENDENT — CAN BE VULGAR.","spanish_example":"¿Qué es esa vaina?","english_example":"What's that thing?","find_it":"Case 10. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/vaina","case":"10","in_dialogue":false,"learning_status":"recognition_sensitive"},{"term":"voz","meaning":"Voice; vocals when referring to the recorded voice in music.","region_and_use":"general Spanish. USE IN THE TAUGHT SETTING.","spanish_example":"La voz suena clara.","english_example":"The vocals sound clear.","find_it":"Case 05. Dialogue: Case 04, Case 05, Case 11, Case 12.","sources":"https://dle.rae.es/voz","case":"05","in_dialogue":true,"learning_status":"active"},{"term":"wepa","meaning":"An exclamation of enthusiasm, encouragement or delight; separately, a friendly greeting in recorded contexts. Those functions are related but distinct.","region_and_use":"Nicaragua, Panama, Dominican Republic, Puerto Rico, Venezuela for the exclamation; greeting labels differ. RECOGNISE FIRST.","spanish_example":"¡Wepa! ¡Terminamos el ensayo!","english_example":"Yes! We've finished rehearsal!","find_it":"Case 04. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/%C2%A1wepa%21 ; https://www.asale.org/damer/wepa","case":"04","in_dialogue":false,"learning_status":"recognition"},{"term":"yuma","meaning":"A person from the United States, or a foreign person in another recorded Cuban sense; the word alone does not establish a friendly or hostile tone.","region_and_use":"Cuba. RECOGNISE FIRST.","spanish_example":"En el comentario cubano, «yuma» se refiere a una visitante extranjera.","english_example":"In the Cuban comment, “yuma” refers to a foreign visitor.","find_it":"Case 10. Supplementary; not spoken in a main dialogue.","sources":"https://www.asale.org/damer/yuma","case":"10","in_dialogue":false,"learning_status":"recognition"}]};
